<?phpnamespace hema\wechat;use app\common\model\Setting;use think\facade\Cache;use hema\Http;class Wechat{	private $config;	private $api_url = 'https://api.weixin.qq.com';    private $error;    	/**	 * 构造函数	 */	public function __construct()	{	    $this->config = Setting::getItem('wechat');	}		/**     * 请求数据验证     **/    private function result($result)    {        if(isset($result['errcode']) and $result['errcode']!=0){			$this->error = 'code：' . $result['errcode'] . '，msg：' . $result['errmsg'];			return false;		}		return $result;    }        	/**	 * 发送模板消息(管理) - 提现申请通知	 */	public function sendApplyCash($open_id,$money,$account)    {         //获取模板消息编号        $template_id = Setting::getItem('wxtpl')['apply_cash'];         if(empty($template_id)){            return true;        }        $queryarr = [            'touser' => $open_id,            'template_id' => trim($template_id),            'url' => base_url(),            /*            'miniprogram' => [                'appid' => '',                'pagepath' => 'pages/index/index'            ],            */            'data' => [                'amount1' => [                    'value' => $money,//提现金额                ],                'thing2' => [                    'value' => $account,//提现账户                ],                'time3' => [                    'value' => date('Y/m/d H:i:s',time()),//提现时间                ],            ]        ];        return $this->sendWechatMsg($queryarr);//执行发布模板消息    }    /**	 * 发送模板消息(商户) - 新订单通知	 */	public function sendNewsOrder($open_id,$order_no,$money)    {         //获取模板消息编号        $template_id = Setting::getItem('wxtpl')['news_order'];         if(empty($template_id)){            return true;        }        $queryarr = [            'touser' => $open_id,            'template_id' => trim($template_id),            'url' => base_url(),            /*            'miniprogram' => [                'appid' => '',                'pagepath' => 'pages/index/index'            ],            */            'data' => [                'character_string2' => [                    'value' => $order_no,//订单编号                ],                'amount3' => [                    'value' => $money,//订单金额                ],                'time5' => [                    'value' => date('Y/m/d H:i:s',time()),//下单时间                ],            ]        ];        return $this->sendWechatMsg($queryarr);//执行发布模板消息    }    /**	 * 发送模板消息(商户) - 注册成功通知	 */	public function sendRegisterSuccess($open_id,$name,$phone)    {         //获取模板消息编号        $template_id = Setting::getItem('wxtpl')['register_success'];         if(empty($template_id)){            return true;        }        $queryarr = [            'touser' => $open_id,            'template_id' => trim($template_id),            'url' => base_url(),            /*            'miniprogram' => [                'appid' => '',                'pagepath' => 'pages/index/index'            ],            */            'data' => [                'thing2' => [                    'value' => $name,//姓名                ],                'phone_number3' => [                    'value' => $phone,//电话                ],                'time7' => [                    'value' => date('Y/m/d H:i:s',time()),//注册时间                ],            ]        ];        return $this->sendWechatMsg($queryarr);//执行发布模板消息    }    /**	 * 发送模板消息(商户) - 用户申请退款通知	 */	public function sendApplyRefund($open_id,$order_no,$money)    {         //获取模板消息编号        $template_id = Setting::getItem('wxtpl')['apply_refund'];         if(empty($template_id)){            return true;        }        $queryarr = [            'touser' => $open_id,            'template_id' => trim($template_id),            'url' => base_url(),            /*            'miniprogram' => [                'appid' => '',                'pagepath' => 'pages/index/index'            ],            */            'data' => [                'character_string7' => [                    'value' => $order_no,//订单编号                ],                'amount5' => [                    'value' => $money,//订单金额                ],                'time12' => [                    'value' => date('Y/m/d H:i:s',time()),//退款时间                ],            ]        ];        return $this->sendWechatMsg($queryarr);//执行发布模板消息    }    /**	 * 发送模板消息(商户) - 提现到账通知	 */	public function sendCashAccount($open_id,$money,$account)    {         //获取模板消息编号        $template_id = Setting::getItem('wxtpl')['cash_account'];         if(empty($template_id)){            return true;        }        $queryarr = [            'touser' => $open_id,            'template_id' => trim($template_id),            'url' => base_url(),            /*            'miniprogram' => [                'appid' => '',                'pagepath' => 'pages/index/index'            ],            */            'data' => [                'amount2' => [                    'value' => $money,//提现金额                ],                'thing4' => [                    'value' => $account,//提现账户                ],                'time3' => [                    'value' => date('Y/m/d H:i:s',time()),//到账时间                ],            ]        ];        return $this->sendWechatMsg($queryarr);//执行发布模板消息    }    /**     * 发布模板消息    */    private function sendWechatMsg(array $queryarr = [])    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/message/template/send?access_token='.$access_token;        return $this->result(json_decode(Http::post($url,json_encode($queryarr)),true));    }    /**     * 生成二维码 （帐号管理-生成带参数的二维码）     */        public function qrcodeCreate($action_name='QR_STR_SCENE',$scene='login',$expire_seconds=7200)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/qrcode/create?access_token=' . $access_token;        /**         * 二维码类型         * QR_SCENE为临时的整型参数值，QR_STR_SCENE为临时的字符串参数值         * QR_LIMIT_SCENE为永久的整型参数值，QR_LIMIT_STR_SCENE为永久的字符串参数值         */        $queryarr['action_name'] = $action_name;        //设置临时二维码过期时间        if($action_name=='QR_STR_SCENE' or $action_name=='QR_SCENE'){            $queryarr['expire_seconds'] = $expire_seconds;        }        if($action_name=='QR_STR_SCENE' or $action_name=='QR_LIMIT_STR_SCENE'){            $queryarr['action_info']['scene']['scene_str'] = $scene;        }else{            $queryarr['action_info']['scene']['scene_id'] = (int)$scene;        }        $result = json_decode(Http::post($url, hema_json($queryarr)),true);                if(isset($result['ticket'])){			$rs = Http::get('https://mp.weixin.qq.com/cgi-bin/showqrcode?ticket='.urlencode($result['ticket']));			$path = 'temp';    		if(!file_exists('./'.$path)){    			mkdir($path,0777,true);    		}    		//获取的二维码数据存储到指定的文件    		file_put_contents('./'.$path . '/local_login_qrcode.png',$rs);    		return $result['ticket'];		}		$this->error = 'code：' . $result['errcode'] . ' msg：' . $result['errmsg'];        return false;    }    /**     * 新增草稿 - 图文消息     */    public function addDraft(array $data)    {        $queryarr['articles'] = array();        for($n=0;$n<sizeof($data);$n++){                array_push($queryarr['articles'],[                'title' => $data[$n]['title'],                'author' => $data[$n]['author'],                'digest' => $data[$n]['digest'],                'content' => str_ireplace('"','\'',$data[$n]['wx_content']),                'content_source_url' => base_url(),                'thumb_media_id' => $data[$n]['media_id']            ]);        }        $access_token = $this->getAccessToken();        //上传到微信服务器        $url = $this->api_url . '/cgi-bin/draft/add?access_token='.$access_token;        $result = json_decode(Http::post($url,hema_json($queryarr)),true);        if(!isset($result['media_id'])){            $this->error = 'code：' . $result['errcode'] . '，msg：' . $result['errmsg'];			return false;        }        return $result;     //$result['media_id'];    }    /**     * 上传图文消息内的图片 - 到微信端（永久素材） - 公众号端     *  图片仅支持jpg/png格式，大小必须在1MB以下     */    public function upWechatUrl(array $img)    {        $access_token = $this->getAccessToken();        for($n=0;$n<sizeof($img);$n++){            $real_path = web_path() . 'uploads/' . $img[$n]['file_path'];            //上传到微信服务器            $url = $this->api_url . '/cgi-bin/media/uploadimg?access_token='.$access_token;            $queryarr['media'] = curl_file_create($real_path,'image/jpeg',$img[$n]['file_path']);//获取要上传的二进制文件            $result = json_decode(Http::post($url,$queryarr),true);            if(!isset($result['url'])){                return false;//上传错误，一般是图片不符合要求            }            $img[$n]['url'] = $result['url'];        }        return $img;    }    /**     * 删除素材文件     */    public function delMaterial(string $media_id)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/material/del_material?access_token='.$access_token;        $queryarr = [            'media_id' => $media_id        ];        return $this->result(json_decode(Http::post($url, hema_json($queryarr)),true));    }    /**     * 删除草稿 - 图文消息     */    public function delDraft(string $media_id)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/draft/delete?access_token='.$access_token;        $queryarr = [            'media_id' => $media_id        ];        return $this->result(json_decode(Http::post($url, hema_json($queryarr)),true));    }    /**     * 修改草稿 - 图文消息     */    public function editDraft(array $data, string $media_id)    {        $access_token = $this->getAccessToken();        for($n=0;$n<sizeof($data);$n++){            $queryarr = [                'media_id' => $media_id,                'index' => $data[$n]['id'],                'articles' => [                    'title' => $data[$n]['title'],                    'author' => $data[$n]['author'],                    'digest' => $data[$n]['digest'],                    'content' => str_ireplace('"','\'',$data[$n]['wx_content']),                    'content_source_url' => base_url(),                    'thumb_media_id' => $data[$n]['media_id']                ]            ];            //上传到微信服务器            $url = $this->api_url . '/cgi-bin/draft/update?access_token='.$access_token;            if(!$this->result(json_decode(Http::post($url,hema_json($queryarr)),true))){    			return false;    		}        }        return true;    }    /**     * 上传素材文件     */    public function addMaterial(string $file_path = '', int $file_type = 10, string $name = '', string $introduction = '')    {        // 验证文件并上传        if($file_type==10){ //图片（image）: 2M，支持bmp/png/jpeg/jpg/gif格式            $type = 'image';            $mimetype = 'image/jpeg';        }        if($file_type==20){ //语音（voice）：2M，播放长度不超过60s，mp3/wma/wav/amr格式            $type = 'voice';            $mimetype = 'audio/mpeg';        }        if($file_type==30){ //视频（video）：10MB，支持MP4格式            $type = 'video';            $mimetype = 'video/mp4';            $queryarr['description'] = '{"title":"'.$name.'","introduction":"'.$introduction.'"}';        }        $access_token = $this->getAccessToken();        $real_path = web_path() . 'uploads/' . $file_path;        //上传到微信服务器        $url = $this->api_url . '/cgi-bin/material/add_material?access_token='.$access_token.'&type='.$type;        $queryarr['media'] = curl_file_create($real_path,$mimetype,$file_path);//获取要上传的二进制文件        $result = json_decode(http_post($url,$queryarr),true);        write_log($result,__DIR__);        if(!isset($result['media_id'])){            $this->error = 'code：' . $result['errcode'] . '，msg：' . $result['errmsg'];			return false;        }        return $result;     //$result['media_id'];    }    /**     * 根据OpenID列表群发公众号信息     */    public function sendMass($msg, $open_id)    {        //图文消息        if($msg['msg_type']['value']=='news'){            $queryarr = [                'mpnews' => [                    'media_id' => $msg['content']                ],                'msgtype' => 'mpnews',                'send_ignore_reprint' => $msg['send_ignore_reprint']            ];        }        //文本消息        if($msg['msg_type']['value']=='text'){            $queryarr = [                'msgtype' => 'text',                'text' => [                    'content' => $msg['content']                ]            ];        }        //语音消息        if($msg['msg_type']['value']=='voice'){            $queryarr = [                'voice' => [                    'media_id' => $msg['content']                ],                'msgtype' => 'voice'            ];        }        //图片消息        if($msg['msg_type']['value']=='image'){            $queryarr = [                'images' => [                    'media_ids' => [                        0 => $msg['content']                    ],                    'recommend' => $msg['recommend'],                    'need_open_comment' => $msg['need_open_comment'],                    'only_fans_can_comment' => $msg['only_fans_can_comment']                ],                'msgtype' => 'image'            ];        }        //视频消息        if($msg['msg_type']['value']=='video'){            $queryarr = [                'mpvideo' => [                    'media_id' => $msg['content'],                    'title' => $msg['title'],                    'description' => $msg['description']                ],                'msgtype' => 'mpvideo'            ];        }        //卡券消息        if($msg['msg_type']['value']=='wxcard'){            $queryarr = [                'wxcard' => [                    'card_id' => $msg['content']                ],                'msgtype' => 'wxcard'            ];        }        $queryarr['touser'] = $open_id;        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/message/mass/send?access_token='.$access_token;        return $this->result(json_decode(Http::post($url, hema_json($queryarr)),true));    }    /**     * 删除公众号群发记录     */    public function deleteMass(int $msg_id)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/message/mass/delete?access_token='.$access_token;        $queryarr = ['msg_id' => $msg_id];        return $this->result(json_decode(Http::post($url, hema_json($queryarr)),true));    }    /**     * 向公众号发布预览消息     */    public function previewMsg(array $data, string $open_id)    {        //图文消息        if($data['msg_type']=='news'){            $queryarr = [                'mpnews' => ['media_id' => $data['content']],                'msgtype' => 'mpnews'            ];        }        //文本消息        if($data['msg_type']=='text'){            $queryarr = [                'text' => ['content' => $data['content']],                'msgtype' => 'text'            ];        }        //语音消息        if($data['msg_type']=='voice'){            $queryarr = [                'voice' => ['media_id' => $data['content']],                'msgtype' => 'voice'            ];        }        //图片消息        if($data['msg_type']=='image'){            $queryarr = [                'image' => ['media_id' => $data['content']],                'msgtype' => 'image'            ];        }        //视频消息        if($data['msg_type']=='video'){            $queryarr = [                'mpvideo' => ['media_id' => $data['content']],                'msgtype' => 'mpvideo'            ];        }        //卡券消息        if($data['msg_type']=='wxcard'){            $queryarr = '{                "wxcard":{                    "card_id":"'.$data['content'].'",                    "card_ext": "{                        "code":"",                        "openid":"",                        "timestamp":"",                        "signature":""                    }                    "msgtype":"wxcard"                }';            $queryarr = [                'wxcard' => [                    'card_id' => $data['content'],                    'card_ext' => [                        'code' => '',                        'openid' => '',                        'timestamp' => '',                        'signature' => ''                    ]                ],                'msgtype' => 'wxcard'            ];        }        $queryarr['touser'] = $open_id;        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/message/mass/preview?access_token='.$access_token;        return $this->result(json_decode(Http::post($url, hema_json($queryarr)),true));    }     /**    * 自定义菜单    */    public function creatMenu(array $menu)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/menu/create?access_token='.$access_token;        $queryarr = [           'button' => $menu        ];        return $this->result(json_decode(Http::post($url, hema_json($queryarr)),true));    }        /**     * 获取用户基本信息(UnionID机制)     */     public function getUserInfo($openid)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/user/info?access_token='.$access_token;        $queryarr = [            'openid' => $openid,            'lang' => 'zh_CN',        ];        return $this->result(json_decode(Http::get($url, $queryarr),true));     }    /**     * 批量获取用户基本信息     * 最多支持一次拉取100条     */     public function getUserInfoList($openid)    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/user/info/batchget?access_token='.$access_token;        //重组数据格式        $arr = [];        foreach ($openid as $item){            $arr[] = [                'openid' => $item,                'lang' => 'zh_CN',            ];        }        //分组数据，每组100个，最多处理10组        $temp = [];//临时数组        $user_list = [];//用户组        foreach ($arr as $item){            $temp[] = $item;            if(sizeof($temp) == 100){                $user_list[] = $temp;                $temp = [];//初始临时数组            }        }        if(sizeof($temp) > 0){            $user_list[] = $temp;        }                $list = [];//初始用户列表        //每组100人        foreach ($user_list as $item){            $queryarr = [                'user_list' => $item,            ];            $result = json_decode(Http::post($url,hema_json($queryarr)),true);            foreach ($result['user_info_list'] as $vo){                array_push($list,$vo);            }        }        return $list;    }    /**     * 获取用户列表     * 一次拉取调用最多拉取10000个关注者的OpenID     */     public function getUserList($openid='')    {        $access_token = $this->getAccessToken();        $url = $this->api_url . '/cgi-bin/user/get?access_token='.$access_token;        $queryarr = [            'next_openid' => $openid,//上一批列表的最后一个OPENID，不填默认从头开始拉取        ];        return  $this->result(json_decode(Http::get($url, $queryarr),true));         //$result['data']['openid'];    }        /**     * 获取令牌    */    private function getAccessToken()    {        $access_token = Cache::get('wechat_access_token','');        if(empty($access_token)){            $config = $this->config;    //获取第三方配置            //重新获取            $url = $this->api_url . '/cgi-bin/token';            $queryarr = [                'grant_type' => 'client_credential',                'appid' => $config['app_id'],                'secret' => $config['app_secret']            ];            $result = json_decode(Http::get($url, $queryarr),true);            if(isset($result['access_token'])){                $access_token = $result['access_token'];                Cache::set('wechat_access_token',$access_token,3000);            }        }        return $access_token;    }        /**     * 通过code换取网页授权access_token    */    public function getAuth($code)    {        $access_token = Cache::get('wechat_auth_access_token','');        if(empty($access_token)){            $config = $this->config;    //获取第三方配置            //重新获取            $url = $this->api_url . '/sns/oauth2/access_token';            $queryarr = [                'appid' => $config['app_id'],                'secret' => $config['app_secret'],                'code' => $code,                'grant_type' => 'authorization_code'            ];            $result = json_decode(Http::get($url, $queryarr),true);            if(isset($result['access_token'])){                $access_token = $result;                Cache::set('wechat_auth_access_token',$access_token,3000);            }        }        return $access_token;    }    public function getError()    {        return $this->error;    }}